package merge

import "testing"

type gsrWitnessLister struct {
	items []string
}

func (l gsrWitnessLister) List() []string {
	return l.items
}

func TestGSRWitness(t *testing.T) {
	a := gsrWitnessLister{[]string{"a"}}
	b := gsrWitnessLister{[]string{"a"}}
	got := Merge(a, b)
	want := []string{"a"}

	if len(got) != len(want) {
		t.Fatalf("Merge(a, b) = %q, want %q", got, want)
	}
	for i := range got {
		if got[i] != want[i] {
			t.Fatalf("Merge(a, b) = %q, want %q", got, want)
		}
	}
}

package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	putCalls int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.putCalls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessStore{}
	_ = Save(ctx, store, "id", "a", "b")

	if store.putCalls >= 2 {
		t.Fatalf("Save called Put %d times on a cancelled context, want < 2", store.putCalls)
	}
}

