package poll

import (
	"context"
	"testing"
)

type gsrWitnessSource struct {
	calls int
}

func (s *gsrWitnessSource) Get(ctx context.Context, key string) (string, error) {
	s.calls++
	if ctx.Err() != nil {
		return "", ctx.Err()
	}
	return "", ErrNotReady
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	src := &gsrWitnessSource{}
	_, _ = Poll(ctx, src, "key")

	if src.calls != 1 {
		t.Fatalf("Poll() made %d Get calls with an already-cancelled context, want 1", src.calls)
	}
}

