package upload

import (
	"errors"
	"testing"
)

type gsrWitnessWriter struct {
	flushCalls int
}

func (w *gsrWitnessWriter) Write(part string) error {
	return errors.New("failed")
}

func (w *gsrWitnessWriter) Flush() error {
	w.flushCalls++
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrWitnessWriter{}
	err := Upload(w, []string{"part1"})
	if err == nil {
		t.Skip("gsr-setup: expected Upload to return an error when Write fails")
	}
	if w.flushCalls != 0 {
		t.Fatalf("flush calls after failed write = %v, want 0", w.flushCalls)
	}
}

package upload

import (
	"errors"
	"testing"
)

type gsrWitnessWriter struct {
	flushCalled bool
}

func (w *gsrWitnessWriter) Write(part string) error {
	return errors.New("injected error")
}

func (w *gsrWitnessWriter) Flush() error {
	w.flushCalled = true
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrWitnessWriter{}
	err := Upload(w, []string{"part1"})
	if err == nil {
		t.Skip("gsr-setup: Upload did not return the injected Write error")
	}
	if w.flushCalled {
		t.Fatalf("Upload() called Flush() after a failed Write, want no Flush()")
	}
}

