}

func (w *gsrFailingWriter) Flush() error {
	w.flushed = true
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrFailingWriter{}
	_ = Upload(w, []string{"part1"})
	if w.flushed {
		t.Fatalf("Upload() flushed after failed Write = %v, want %v", w.flushed, false)
	}
}

