package memo

import "testing"

func TestGSRWitness(t *testing.T) {
	m := New()
	calls := 0
	load := func(k string) (string, error) {
		calls++
		return "val", nil
	}

	_, err := m.Get("k", load)
	if err != nil {
		t.Skip("gsr-setup: unexpected error from first Get")
	}

	_, err = m.Get("k", load)
	if err != nil {
		t.Skip("gsr-setup: unexpected error from second Get")
	}

	if calls != 1 {
		t.Fatalf("calls to load = %d, want 1", calls)
	}
}

